<?php
namespace App\Services;use App\Models\Product;use Illuminate\Support\Collection;class CartService{public function raw():array{return session('cart',[]);}public function add(Product $p,int $q=1):void{abort_unless($p->status==='active'&&$p->in_stock,422,'This product is not available.');$c=$this->raw();$n=min(99,($c[$p->id]??0)+max(1,$q));if($p->track_stock)$n=min($n,$p->stock_quantity);$c[$p->id]=$n;session(['cart'=>$c]);}public function update(Product $p,int $q):void{$c=$this->raw();if($q<=0)unset($c[$p->id]);else{$q=min(99,$q);if($p->track_stock)$q=min($q,$p->stock_quantity);$c[$p->id]=$q;}session(['cart'=>$c]);}public function remove(Product $p):void{$c=$this->raw();unset($c[$p->id]);session(['cart'=>$c]);}public function clear():void{session()->forget('cart');}public function items():Collection{$c=$this->raw();if(!$c)return collect();return Product::query()->whereIn('id',array_keys($c))->get()->map(function(Product $p)use($c){$q=(int)$c[$p->id];return['product'=>$p,'quantity'=>$q,'unit_price'=>$p->current_price,'line_total'=>round($p->current_price*$q,2)];})->values();}public function summary():array{$items=$this->items();$subtotal=round((float)$items->sum('line_total'),2);$shipping=round((float)$items->sum(fn($i)=>((float)($i['product']->shipping_price??0))*$i['quantity']),2);return['items'=>$items,'subtotal'=>$subtotal,'shipping'=>$shipping,'total'=>round($subtotal+$shipping,2),'count'=>$items->sum('quantity')];}}
